def neurone(x, w, b):
    return 1 if sum(wi * xi for wi, xi in zip(w, x)) + b > 0 else 0

def apprendre(exemples, n_epoques):
    d = len(exemples[0][0])
    w = [0] * d
    b = 0
    for epoque in range(1, n_epoques + 1):
        erreurs = 0
        for x, y in exemples:
            s = neurone(x, w, b)
            if s != y:
                for i in range(d):
                    w[i] += (y - s) * x[i]
                b += (y - s)
                erreurs += 1
        if erreurs == 0:
            return (w, b, epoque)
    return (w, b, n_epoques)

