question.answer:
import numpy as np

def sigmoide(z):
    return 1.0 / (1.0 + np.exp(-z))

def passe_avant(X, W1, b1, W2, b2):
    Z1 = X @ W1 + b1
    A1 = sigmoide(Z1)
    Z2 = A1 @ W2 + b2
    A2 = sigmoide(Z2)
    return (Z1, A1, Z2, A2)

def gradients(X, y, W1, b1, W2, b2):
    n = X.shape[0]
    Z1, A1, Z2, A2 = passe_avant(X, W1, b1, W2, b2)
    D2 = (A2 - y) / n
    gW2 = A1.T @ D2
    gb2 = D2.sum(axis=0)
    D1 = (D2 @ W2.T) * A1 * (1 - A1)
    gW1 = X.T @ D1
    gb1 = D1.sum(axis=0)
    return (gW1, gb1, gW2, gb2)

