question.answer:
def derivee_max(nom):
    table = {'marche': 0.0, 'sigmoide': 0.25, 'tanh': 1.0, 'relu': 1.0}
    return table[nom]

def facteur(nom, couches):
    return format(derivee_max(nom) ** couches, '.4g')
